1	import test from 'node:test';
2	import assert from 'node:assert/strict';
3	import { createInvoice, issueInvoice } from '../src/invoices.js';
4	import { renderInvoiceText } from '../src/render.js';
5	
6	test('renderInvoiceText renders a draft invoice', () => {
7	  const invoiceResult = createInvoice({
8	    customerId: 'C-001',
9	    issueDate: '2026-10-07',
10	    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
11	  });
12	  assert.equal(invoiceResult.ok, true);
13	
14	  const r = renderInvoiceText(invoiceResult.value);
15	  assert.equal(r.ok, true);
16	  const text = r.value;
17	  assert.match(text, /^DRAFT$/m);
18	  assert.match(text, /^Northwind Studio$/m);
19	  assert.match(text, /5x Development \(hour\) @ €95\.00 = €475\.00/);
20	  assert.match(text, /5% off/);
21	  assert.match(text, /VAT:/);
22	  assert.match(text, /Total:/);
23	});
24	
25	test('renderInvoiceText renders an issued invoice with number', () => {
26	  const invoiceResult = createInvoice({
27	    customerId: 'C-001',
28	    issueDate: '2026-10-07',
29	    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
30	  });
31	  assert.equal(invoiceResult.ok, true);
32	
33	  const issueResult = issueInvoice(invoiceResult.value, []);
34	  assert.equal(issueResult.ok, true);
35	
36	  const r = renderInvoiceText(issueResult.value);
37	  assert.equal(r.ok, true);
38	  const text = r.value;
39	  assert.match(text, /^INV-2026-0001$/m);
40	  assert.match(text, /^Northwind Studio$/m);
41	});
42	
43	test('renderInvoiceText renders multiple lines', () => {
44	  const invoiceResult = createInvoice({
45	    customerId: 'C-003',
46	    issueDate: '2026-10-07',
47	    lines: [
48	      { sku: 'DEV-HOUR', qty: 5 },
49	      { sku: 'LOGO-PACK', qty: 1 },
50	      { sku: 'COPY-HOUR', qty: 3 },
51	    ],
52	  });
53	  assert.equal(invoiceResult.ok, true);
54	
55	  const r = renderInvoiceText(invoiceResult.value);
56	  assert.equal(r.ok, true);
57	  const text = r.value;
58	
59	  assert.match(text, /^DRAFT$/m);
60	  assert.match(text, /^Kite & Co$/m);
61	  assert.match(text, /5x Development \(hour\)/);
62	  assert.match(text, /1x Logo package/);
63	  assert.match(text, /3x Copywriting \(hour\)/);
64	  assert.match(text, /Subtotal:/);
65	  assert.match(text, /Discount:/);
66	  assert.match(text, /Total:/);
67	});
68	
69	test('renderInvoiceText formats large amounts with thousands separators', () => {
70	  const invoiceResult = createInvoice({
71	    customerId: 'C-001',
72	    issueDate: '2026-10-07',
73	    lines: [{ sku: 'BRAND-BOOK', qty: 2 }],
74	  });
75	  assert.equal(invoiceResult.ok, true);
76	
77	  const r = renderInvoiceText(invoiceResult.value);
78	  assert.equal(r.ok, true);
79	  const text = r.value;
80	  assert.match(text, /€2,450\.00/); // unitPrice for BRAND-BOOK is 245000 cents = €2,450.00
81	  assert.match(text, /€4,900\.00/); // line total 2 * 245000 = 490000 cents = €4,900.00
82	});
83	
84	test('renderInvoiceText calculates correct total', () => {
85	  const invoiceResult = createInvoice({
86	    customerId: 'C-001',
87	    issueDate: '2026-10-07',
88	    lines: [
89	      { sku: 'DEV-HOUR', qty: 5 },
